import {CROPS,SEASONS} from './model.js';
import {COST_FIELDS,blankEntry,convertBasis,estimateRotation,validateProfile,numberOrNull} from './finance.js';
import {t,number,money,language,locale,date,localizeHTML,translateDOM} from './i18n.js';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const types=[['baseline','My current crops'],['best','My priorities'],['alternate','Water first'],['soil','Soil first'],['climate','Weather first']];
const labels={seed:'Seed',fertilizer:'Fertilizer',labour:'Labour',irrigation:'Irrigation',machinery:'Machinery',transport:'Transport',other:'Other expenses',yield:'Expected harvest',price:'Selling price'};
let context,activeCrop='rice',chartMetric='net';
let profile={area:'',unit:'acre',basis:'acre',budget:'',season:'0',preferred:[]};
let entries={},changes={price:0,yield:0,fertilizer:0,labour:0,downsideYield:20,downsidePrice:20};
try{const saved=JSON.parse(localStorage.getItem('fieldshift-finance-v1')||'null');if(saved){profile={...profile,...saved.profile};entries=saved.entries||{};changes={...changes,...saved.changes};}}catch{}
profile.unit=['acre','ha'].includes(profile.unit)?profile.unit:'acre';profile.basis=['acre','ha'].includes(profile.basis)?profile.basis:'acre';
profile.preferred=Array.isArray(profile.preferred)?profile.preferred.filter(id=>CROPS.some(c=>c.id===id)):[];
profile.season=['0','1','2'].includes(String(profile.season))?String(profile.season):'0';
for(const key of Object.keys(changes)){const n=numberOrNull(changes[key]);changes[key]=Math.max(key.startsWith('downside')?0:-50,Math.min(key.startsWith('downside')?100:50,n??0));}
entries=Object.fromEntries(CROPS.filter(c=>entries?.[c.id]&&typeof entries[c.id]==='object').map(c=>[c.id,entries[c.id]]));
const cropName=id=>CROPS.find(c=>c.id===id)?.name||id;
function save(){try{localStorage.setItem('fieldshift-finance-v1',JSON.stringify({profile,entries,changes}));}catch{}}
function field(id,label,value,options=''){return `<label>${label}<input id="${id}" type="number" ${options.includes('min=')?'':'min="0"'} ${options.includes('max=')?'':'max="1000000000"'} step="any" inputmode="decimal" value="${esc(value)}" ${options}></label>`;}
function readProfile(){for(const k of ['area','unit','budget','season'])profile[k]=$('farm-'+k).value;profile.preferred=Array.from(document.querySelectorAll('[name=preferred-crop]:checked'),e=>e.value);save();render();}
function readCrop(){
  const entry=entries[activeCrop]||blankEntry();for(const k of [...COST_FIELDS,'yield','price'])if($('cost-'+k))entry[k]=$('cost-'+k).value;
  entry.source=$('cost-source').value;entry.updatedAt=new Date().toISOString();entries[activeCrop]=entry;save();render();
}
function fillCrop(){
  const entry=entries[activeCrop]||blankEntry();
  $('crop-budget-fields').innerHTML=COST_FIELDS.map(k=>field('cost-'+k,labels[k]+' · INR',entry[k]??'')).join('')+(activeCrop==='fallow'?'<p>Rest periods have no harvest revenue. Enter any residue-management costs; enter 0 where there is no cost.</p>':field('cost-yield','Expected harvest · kg',entry.yield??'')+field('cost-price','Selling price · INR / kg',entry.price??''));
  $('cost-source').value=entry.source||'';
  $('budget-basis-label').textContent=profile.basis==='acre'?'Costs and harvest quantity below are per acre, per crop season.':'Costs and harvest quantity below are per hectare, per crop season.';
  $('crop-budget-fields').querySelectorAll('input').forEach(input=>input.addEventListener('change',readCrop));
  $('cost-source').onchange=readCrop;translateDOM($('farm-finances'));
}
function calculations(){return context?Object.fromEntries(types.map(([key])=>[key,estimateRotation(context.results[key].ids,profile,entries,changes)])):{};}
function render(){
  if(!$('finance-validation'))return;
  const attempted=profile.area!==''||profile.budget!=='';
  $('finance-validation').textContent=attempted&&!validateProfile(profile)?'Enter a positive farm area and a valid non-negative budget. Incomplete estimates will not be calculated.':'';
  const results=calculations();if(!context)return;
  for(const [key] of types){
    const card=document.querySelector(`[data-rotation="${key}"] .rotation-body`);if(!card)continue;
    let box=card.querySelector('.finance-inline');if(!box){box=document.createElement('section');box.className='finance-inline';card.append(box);}
    const r=results[key];
    box.innerHTML='<h4>My money estimate</h4>'+(r.complete?`<div class="finance-metrics"><div><span>Investment needed</span><strong>${money(r.cost)}</strong></div><div><span>Estimated net income</span><strong class="${r.net<0?'negative':''}">${money(r.net)}</strong></div><div><span>Downside net income</span><strong class="${r.downsideNet<0?'negative':''}">${money(r.downsideNet)}</strong></div></div><p>${r.budgetGap===null?'Add your budget to check affordability.':r.budgetGap>0?esc(t('Above your budget by {{amount}}.',{amount:money(r.budgetGap)})):'Within the entered cultivation budget.'}</p><p>Farmer-entered scenario, not guaranteed earnings. Costs cover all three seasons before any harvest income is reused.</p>`:`<p>Add farm area, costs, harvest quantity and selling prices to estimate this plan.</p><button class="text-button" data-add-budget="${key}">Add my estimates →</button>`);
    const preferred=context.results[key].ids.filter(id=>profile.preferred.includes(id));
    if(preferred.length)box.insertAdjacentHTML('beforeend',`<p>${esc(t('Includes preferred crops: {{crops}}',{crops:preferred.map(id=>t(cropName(id))).join(', ')}))}</p>`);
  }
  $('financial-comparison').innerHTML=`<p>All values use your entries and the selected financial scenario. No live market prices or NASA yield predictions are used.</p><div class="financial-chart-controls" role="group" aria-label="Financial chart metric">${[['cost','Investment needed'],['revenue','Gross revenue'],['net','Net income']].map(([key,label])=>`<button class="button secondary" data-financial-chart="${key}" aria-pressed="${key===chartMetric}">${label}</button>`).join('')}</div><div class="financial-chart" aria-label="Financial comparison chart">${types.map(([key,label])=>{const r=results[key],max=Math.max(1,...Object.values(results).filter(v=>v.complete).map(v=>Math.abs(v[chartMetric])));return `<div class="financial-chart-row"><span>${label}</span><div>${r.complete?`<i class="${r[chartMetric]<0?'negative':''}" style="width:${Math.abs(r[chartMetric])/max*100}%"></i>`:''}</div><b>${r.complete?money(r[chartMetric]):t('Needs inputs')}</b></div>`;}).join('')}</div>
    <div class="table-scroll"><table><thead><tr><th>Comparison</th>${types.map(([,label])=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${[['cost','Cultivation cost'],['revenue','Gross revenue'],['net','Net income'],['downsideNet','Downside net income'],['loss','Potential downside loss'],['costPerAcre','Cost per acre']].map(([metric,label])=>`<tr><th>${label}</th>${types.map(([key])=>`<td>${results[key].complete?money(results[key][metric]):t('Needs inputs')}</td>`).join('')}</tr>`).join('')}<tr><th>Return on investment</th>${types.map(([key])=>`<td>${results[key].complete&&results[key].roi!==null?number(results[key].roi,1)+'%':'—'}</td>`).join('')}</tr><tr><th>Crop water need · mm / cycle</th>${types.map(([key])=>`<td>${number(context.results[key].need)}</td>`).join('')}</tr><tr><th>Soil comparison score / 100</th>${types.map(([key])=>`<td>${number(context.results[key].scores.soil)}</td>`).join('')}</tr></tbody></table></div>
    <p>Net income = gross revenue − entered costs. Unpaid family labour, land rent, interest and other omitted costs can overstate income. Add these under the appropriate cost or Other expenses.</p><p>Financial results compare the selected plans. The agronomic priority ranking still uses the disclosed illustrative income index, not these monetary estimates.</p>
    <h4>Break-even check for the selected plan</h4><div id="break-even"></div>`;
  renderSelected();translateDOM();
}
function renderSelected(){
  if(!context)return;const key=document.querySelector('[data-plan][aria-pressed=true]')?.dataset.plan||'best',r=calculations()[key],plan=context.results[key];
  if($('break-even'))$('break-even').innerHTML=r.complete?`<div class="table-scroll"><table><thead><tr><th>Crop</th><th>Break-even price · INR/kg</th><th>Break-even harvest · kg/acre</th><th>Source / entered date</th></tr></thead><tbody>${r.parts.map(p=>`<tr><td>${cropName(p.id)}</td><td>${p.breakEvenPrice===null?'—':number(p.breakEvenPrice,2)}</td><td>${p.breakEvenYieldPerAcre===null?'—':number(p.breakEvenYieldPerAcre,1)}</td><td>${esc(entries[p.id]?.source||t('Farmer estimate'))}<br>${entries[p.id]?.updatedAt?date(entries[p.id].updatedAt):''}</td></tr>`).join('')}</tbody></table></div><p>A dash means the calculation is undefined because cost, price or harvest quantity is zero. Rest periods do not have a harvest break-even value.</p>`:'<p>Complete the selected plan’s estimates to see break-even values.</p>';
  $('farming-calendar').innerHTML=`<p>Illustrative Southern Karnataka calendar. Planting is assumed at the start of each season; confirm local dates and varieties before planting.</p><div class="calendar-grid">${plan.crops.map((crop,i)=>{const start=new Date(Date.UTC(2024,SEASONS[i].months[0]-1,1));const harvest=new Date(start.getTime()+Math.max(0,crop.days-1)*86400000);return `<article class="calendar-card ${+profile.season===i?'focused':''}"><h4>${crop.name}</h4><strong>${SEASONS[i].range}</strong><p>${crop.days?esc(t('Approximate duration: {{days}} days',{days:number(crop.days)})):'Rest field with retained residues'}</p><p>${crop.days?esc(t('Planting: {{month}}',{month:new Intl.DateTimeFormat(locale(),{month:'long'}).format(start)})):'No planting assumed'}</p><p>${crop.days?esc(t('Approximate harvest: {{month}}',{month:new Intl.DateTimeFormat(locale(),{month:'long'}).format(harvest)})):''}</p><p>${crop.days?esc(t('After harvest: about {{days}} days before the next season.',{days:number(SEASONS[i].days-crop.days)})):'Keep the ground covered; bare soil increases exposure.'}</p></article>`;}).join('')}</div><p>Ground cover between crops is uncertain. Ask locally about residue retention or a suitable cover crop; no cover-crop yield or cost is assumed here.</p>`;
  $('water-soil-details').innerHTML=`<div class="table-scroll"><table><thead><tr><th>Crop</th><th>Estimated water need · mm</th><th>Rain during growth · mm</th><th>Possible water gap · mm</th></tr></thead><tbody>${plan.parts.map(p=>`<tr><td>${p.crop.name}</td><td>${number(p.need)}</td><td>${number(p.rain)}</td><td>${number(p.deficit)}</td></tr>`).join('')}</tbody></table></div><p>Rainfall capture and irrigation are simplified assumptions. Water gaps are not exact irrigation prescriptions. Soil scores describe crop diversity, legumes and assumed cover, not measured fertility or erosion.</p>`;
  translateDOM();
}
function printReport(){
  if(!context)return;const key=document.querySelector('[data-plan][aria-pressed=true]')?.dataset.plan||'best',plan=context.results[key],r=calculations()[key];
  const frame=document.createElement('iframe');frame.className='report-frame';frame.title=t('Farming report');document.body.append(frame);
  const html=`<!doctype html><html lang="${language()}"><head><meta charset="utf-8"><title>Field Shift — ${t('Farming report')}</title><style>body{font:15px/1.7 'Nirmala UI','Noto Sans',sans-serif;color:#244d3d;margin:30px}h1{font-size:28px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #d4dec9;padding:8px;text-align:left}section{break-inside:avoid}small{font-size:12px}@page{margin:16mm}button{display:none}</style></head><body><h1>Field Shift · Farming report</h1><p>${esc(context.location.name)} · ${context.location.lat}, ${context.location.lon}</p><p>Farm area: ${esc(profile.area||'—')} ${profile.unit==='ha'?'hectares':'acres'} · Budget: ${money(numberOrNull(profile.budget))}</p><h2>${types.find(p=>p[0]===key)[1]}</h2><p>${plan.crops.map(c=>t(c.name)).join(' → ')}</p><p>NASA POWER · ${context.climate.annual[0].year}–${context.climate.annual.at(-1).year} · ${esc(context.mode)}</p><p>Regional historical estimates, not field measurements or forecasts.</p>${r.complete?`<table><tr><th>Cultivation cost</th><td>${money(r.cost)}</td></tr><tr><th>Gross revenue</th><td>${money(r.revenue)}</td></tr><tr><th>Net income</th><td>${money(r.net)}</td></tr><tr><th>Downside net income</th><td>${money(r.downsideNet)}</td></tr></table>`:'<p>Financial estimates are incomplete. Missing values have not been replaced with invented prices or yields.</p>'}<h2>Water and soil</h2>${$('water-soil-details').innerHTML}<h2>Farming calendar</h2>${$('farming-calendar').innerHTML}<h2>Financial assumptions</h2><p>${esc(t('Price change {{price}}%; harvest change {{yield}}%; fertilizer change {{fertilizer}}%; labour change {{labour}}%.',Object.fromEntries(['price','yield','fertilizer','labour'].map(k=>[k,number(changes[k])]))))}</p><p>${esc(t('Downside: harvest {{yield}}% lower and price {{price}}% lower than the selected scenario.',{yield:number(changes.downsideYield),price:number(changes.downsidePrice)}))}</p><p>Financial figures use farmer-entered assumptions and are not guaranteed earnings. No live market prices or NASA yield predictions are used.</p>${$('break-even').innerHTML}<h2>Climate scenario</h2><p>${esc(t('Rainfall change {{rain}}%; temperature rise {{temp}}°C; irrigation reduction {{irrigation}}%.',{rain:number(context.scenario.rain),temp:number(context.scenario.temp,1),irrigation:number(context.scenario.irrigationReduction||0)}))}</p><h2>Main risks and limitations</h2><p>${document.querySelector(`[data-rotation="${key}"] .water-evidence strong`)?.textContent||''}</p><p>Soil and water indicators are simplified model estimates. Local varieties, pests, soil depth and weather timing can change outcomes. Confirm the plan with a local agriculture adviser.</p><h2>Sources</h2><p>NASA POWER: <a href="${esc(context.raw._fieldShift.sourceUrl)}">Original data request</a><br>Last successful retrieval: ${esc(context.raw._fieldShift.retrievedAt)}</p><p>Financial inputs: farmer estimates. Satellite imagery is visual context only. Crop traits and the calendar use the app’s disclosed prototype assumptions.</p></body></html>`;
  const localized=localizeHTML(html);frame.srcdoc=localized;frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();};
  setTimeout(()=>frame.remove(),180000);
}
function speak(){
  if(!('speechSynthesis'in window)){$('voice-status').textContent='Speech is unavailable in this browser.';return;}
  speechSynthesis.cancel();const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith(language()));
  if(!voice){$('voice-status').textContent='No voice for this language is installed. You can still read or print the plan.';return;}
  const card=document.querySelector('.rotation-card:not([hidden])');if(!card)return;const utterance=new SpeechSynthesisUtterance(card.innerText);utterance.voice=voice;utterance.lang=voice.lang;utterance.rate=.9;speechSynthesis.speak(utterance);$('voice-status').textContent='Reading the selected plan.';
}
export function initFarmerTools(){
  const section=document.createElement('section');section.id='farm-finances';section.innerHTML=`<h3>Farm size and budget</h3><p>Money estimates are optional. Enter your own local figures; blank inputs remain unknown.</p><div class="form-row">${field('farm-area','Farm area',profile.area,'min="0.0001" max="100000"')}<label>Area unit<select id="farm-unit"><option value="acre">Acres</option><option value="ha">Hectares</option></select></label>${field('farm-budget','Total cultivation budget · INR',profile.budget)}<label>Season to focus on<select id="farm-season">${SEASONS.map((s,i)=>`<option value="${i}">${s.name}</option>`).join('')}</select></label></div><p id="finance-validation" role="status"></p><details class="more-details"><summary>My preferred crops</summary><p>Highlight these crops in the plans. This does not override seasonal eligibility.</p><div class="preferred-crops">${CROPS.filter(c=>c.id!=='fallow').map(c=>`<label><input type="checkbox" name="preferred-crop" value="${c.id}" ${profile.preferred.includes(c.id)?'checked':''}>${c.name}</label>`).join('')}</div></details>
    <details class="more-details" id="budget-editor"><summary>Enter crop costs, harvest and price</summary><p>Use local records or a recent quote. One crop budget is reused each time that crop appears in a rotation. Enter 0 only when an expense is genuinely zero.</p><div class="form-row"><label>Crop<select id="budget-crop">${CROPS.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></label><label>Costs and harvest unit<select id="budget-basis"><option value="acre">Per acre</option><option value="ha">Per hectare</option></select></label></div><p id="budget-basis-label"></p><div id="crop-budget-fields" class="budget-fields"></div><label>Source or local quote <span class="optional">optional</span><input id="cost-source" type="text" maxlength="200" placeholder="e.g. my farm records"></label><p>Seed, fertilizer, labour, irrigation, machinery, transport and other expenses are all included. Add residue-management costs for a rest period too.</p></details><p class="form-hint">Budget entries are saved only in this browser. No financial entries are sent to NASA or place-search services.</p><button type="button" class="text-button" id="clear-finances">Clear my budget entries</button>`;
  document.querySelector('#farm-form .step-actions').before(section);
  $('farm-unit').value=profile.unit;$('farm-season').value=profile.season;$('budget-basis').value=profile.basis;
  section.addEventListener('invalid',event=>{let parent=event.target.parentElement;while(parent&&parent!==section){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}},true);
  for(const id of ['farm-area','farm-unit','farm-budget','farm-season'])$(id).addEventListener('change',readProfile);
  section.querySelectorAll('[name=preferred-crop]').forEach(e=>e.addEventListener('change',readProfile));
  $('budget-crop').addEventListener('change',e=>{activeCrop=e.target.value;fillCrop();});
  $('budget-basis').addEventListener('change',e=>{entries=convertBasis(entries,profile.basis,e.target.value);profile.basis=e.target.value;save();fillCrop();render();});
  $('clear-finances').onclick=()=>{entries={};profile.area='';profile.budget='';$('farm-area').value='';$('farm-budget').value='';save();fillCrop();render();};
  const extra=document.createElement('div');extra.id='farmer-extras';extra.innerHTML=`<details class="more-details" id="finance-results"><summary>Compare investment, income and financial risk</summary><div id="financial-comparison"></div></details><details class="more-details" id="financial-scenarios"><summary>Try a different harvest or selling price</summary><p>Hypothetical changes to your entries, not market forecasts.</p><div class="budget-fields">${[['price','Selling-price change'],['yield','Harvest change'],['fertilizer','Fertilizer-cost change'],['labour','Labour-cost change']].map(([key,label])=>`<label>${label}<output for="financial-${key}">${changes[key]}%</output><input id="financial-${key}" type="range" min="-50" max="50" step="5" value="${changes[key]}"></label>`).join('')}</div><div class="form-row">${field('downside-yield','Downside harvest reduction · %',changes.downsideYield,'max="100"')}${field('downside-price','Downside price reduction · %',changes.downsidePrice,'max="100"')}</div><p>Downside figures apply both reductions together to the selected scenario. They are stress tests, not predicted income ranges.</p><button class="text-button" id="reset-financial">Reset financial scenario</button></details><details class="more-details"><summary>Water and soil comparison</summary><div id="water-soil-details"></div></details><details class="more-details"><summary>Farming calendar</summary><div id="farming-calendar"></div></details><div class="report-actions"><button class="button secondary" id="print-report">Print / Save PDF</button><button class="button secondary" id="read-plan">Listen to this plan</button><button class="text-button" id="stop-reading">Stop reading</button><p id="voice-status" role="status"></p></div>`;
  $('rotations').append(extra);
  for(const k of ['price','yield','fertilizer','labour'])$('financial-'+k).oninput=e=>{changes[k]=+e.target.value;document.querySelector(`output[for="financial-${k}"]`).textContent=number(changes[k])+'%';save();render();};
  for(const k of ['yield','price'])$('downside-'+k).onchange=e=>{if(!e.target.checkValidity()){e.target.reportValidity();return;}changes[k==='yield'?'downsideYield':'downsidePrice']=+e.target.value;save();render();};
  $('reset-financial').onclick=()=>{for(const k of ['price','yield','fertilizer','labour']){changes[k]=0;$('financial-'+k).value=0;document.querySelector(`output[for="financial-${k}"]`).textContent='0%';}save();render();};
  $('print-report').onclick=printReport;$('read-plan').onclick=speak;$('stop-reading').onclick=()=>{window.speechSynthesis?.cancel();$('voice-status').textContent='';};
  document.addEventListener('fieldshift:analysis',e=>{context=e.detail;render();});
  document.addEventListener('fieldshift:language',()=>{window.speechSynthesis?.cancel();if(context)render();});
  document.addEventListener('click',e=>{const chart=e.target.closest('[data-financial-chart]');if(chart){chartMetric=chart.dataset.financialChart;render();}if(e.target.closest('[data-plan]'))renderSelected();const add=e.target.closest('[data-add-budget]');if(add){document.querySelector('.step-nav [data-step="2"]').click();$('budget-editor').open=true;const r=calculations()[add.dataset.addBudget];activeCrop=r.missing.find(id=>id!=='farm')||'rice';$('budget-crop').value=activeCrop;fillCrop();$('farm-finances').scrollIntoView();}});
  fillCrop();
}
